begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','36000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('36000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','comment-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
update public.users set display_name='Comment user '||right(id::text,1) where id::text like '36000000-%';
select pg_temp.login(1);
create temp table ctx as select public.create_project('Comment fixture','Europe/London','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Category' from ctx returning id) select * from c;
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Activity","kind":"other","activity_type":"task","notes":"Durable Activity instructions"}',null)).id;
create temp table decision as select public.create_decision((select id from ctx),'Decision','Durable Decision description',null,'[{"title":"A"},{"title":"B"}]') id;
create temp table note as select public.create_project_note((select id from ctx),'Durable note','Current project information') id;
create temp table original_activity as select to_jsonb(c) doc from public.commitments c where id=(select id from activity);
create temp table original_decision as select to_jsonb(d) doc from public.decisions d where id=(select id from decision);
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('36000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Comment member',case when i=3 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,3) i;
create temp table notifications_before as select count(*) n from public.notifications where project_id=(select id from ctx);
select pg_temp.login(6);
create temp table other as select public.create_project('Other comment project','UTC','GBP','2026-01-01') id;
create temp table other_decision as select public.create_decision((select id from other),'Other?',null,null,'[{"title":"X"},{"title":"Y"}]') id;
select pg_temp.login(1);
create temp table first_comment as select public.create_resource_comment('activity',(select id from activity),E'  Organizer context\nsecond line  ') doc;
select is((select doc->>'body' from first_comment),E'Organizer context\nsecond line','Trimmed plain text preserves line breaks');
select is((select doc->>'project_id' from first_comment),(select id::text from ctx),'Project derived from actual resource');
select is((select doc->>'author_user_id' from first_comment),'36000000-0000-4000-8000-000000000001','Author derived from JWT');
select is((select doc->>'author_name' from first_comment),'Comment user 1','Display name retained without email');
select is(public.create_resource_comment('activity',(select id from activity),E'Organizer context\nsecond line',(select (doc->>'id')::uuid from first_comment))->>'id',(select doc->>'id' from first_comment),'Exact request retry returns same comment');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'Different',(select (doc->>'id')::uuid from first_comment))$$,'22023',null,'Conflicting retry denied');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),E' \n\t ')$$,'22023',null,'Whitespace-only body rejected');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),null)$$,'22023',null,'Null body rejected');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),repeat('x',4001))$$,'22023',null,'Over-limit body rejected');
select lives_ok($$select public.create_resource_comment('activity',(select id from activity),repeat('x',4000))$$,'Maximum body accepted');
select throws_ok($$select public.create_resource_comment('project',(select id from ctx),'No')$$,'42501',null,'Unsupported resource fails closed');
select throws_ok($$select public.create_resource_comment('decision',(select id from activity),'No')$$,'42501',null,'Activity ID cannot be used as Decision');
select throws_ok($$select public.create_resource_comment('activity',(select id from decision),'No')$$,'42501',null,'Decision ID cannot be used as Activity');
select throws_ok($$select public.create_resource_comment('decision',(select id from other_decision),'No')$$,'42501',null,'Organizer cannot write foreign project');
select throws_ok($$select public.delete_resource_comment('decision',(select id from decision),(select (doc->>'id')::uuid from first_comment))$$,'42501',null,'Comment deletion binds exact thread');
select throws_ok($$insert into public.resource_comments(project_id,resource_type,resource_id,author_user_id,author_name,body) values((select id from other),'activity',(select id from activity),auth.uid(),'Spoof','No')$$,'42501',null,'Direct insert cannot spoof project or author');
select throws_ok($$update public.resource_comments set body='Edited'$$,'42501',null,'No comment editing');
select throws_ok($$delete from public.resource_comments$$,'42501',null,'No direct deletion');
select throws_ok($$select app.require_comment_resource('activity',(select id from activity),true)$$,'42501',null,'Private resolver not callable');
select throws_ok($$select app.emit_domain_event('comment.created',(select id from ctx),(select (doc->>'id')::uuid from first_comment),'{}','created')$$,'42501',null,'Direct event spoof denied');
select pg_temp.login(2);
select is(jsonb_array_length(public.get_resource_comments('activity',(select id from activity))->'items'),2,'Member reads resource comments');
create temp table member_comment as select public.create_resource_comment('activity',(select id from activity),'Member reply') doc;
select throws_ok($$select public.delete_resource_comment('activity',(select id from activity),(select (doc->>'id')::uuid from first_comment))$$,'42501',null,'Member cannot moderate another author');
select pg_temp.login(3);
create temp table viewer_comment as select public.create_resource_comment('decision',(select id from decision),'Viewer participates') doc;
select is((select doc->>'can_delete' from viewer_comment),'true','Viewer can delete own');
select throws_ok($$select public.delete_resource_comment('activity',(select id from activity),(select (doc->>'id')::uuid from member_comment))$$,'42501',null,'Viewer cannot moderate');
select lives_ok($$select public.delete_resource_comment('decision',(select id from decision),(select (doc->>'id')::uuid from viewer_comment))$$,'Viewer deletes own');
select lives_ok($$select public.delete_resource_comment('decision',(select id from decision),(select (doc->>'id')::uuid from viewer_comment))$$,'Exact delete retry safe');
select is(jsonb_array_length(public.get_resource_comments('decision',(select id from decision))->'items'),0,'Deleted body absent from read model');
select is((select count(*)::int from public.resource_comments where id=(select (doc->>'id')::uuid from viewer_comment)),0,'Deleted body absent from direct RLS SELECT');
select throws_ok($$select public.create_resource_share_link('decision',(select id from decision))$$,'42501',null,'Comment capability does not permit Viewer share management');
select throws_ok($$select public.resolve_decision((select id from decision),(select id from public.decision_options where decision_id=(select id from decision) limit 1))$$,'42501',null,'Comment capability does not permit Viewer resolution');
select pg_temp.login(1);
select is((select to_jsonb(c) from public.commitments c where id=(select id from activity)),(select doc from original_activity),'Comments never mutate Activity state, Notes or financial fields');
select is((select to_jsonb(d) from public.decisions d where id=(select id from decision)),(select doc from original_decision),'Comments never mutate Decision state or votes');
select is((select body from public.project_notes where id=(select id from note)),'Current project information','Project Notes unaffected');
select lives_ok($$select public.update_project_note((select id from note),'Durable note','Updated current information')$$,'Existing Notes remain editable');
create temp table tokens as select public.create_resource_share_link('activity',(select id from activity)) a,public.create_resource_share_link('decision',(select id from decision)) d;
create temp table join_token as select public.regenerate_project_join_link((select id from ctx)) t;
select pg_temp.login(4);
select is((select count(*)::int from public.resource_comments where project_id=(select id from ctx)),0,'Nonmember sees zero comments');
select throws_ok($$select public.get_resource_comments('activity',(select id from activity))$$,'42501',null,'Nonmember read RPC denied');
select throws_ok($$select public.create_resource_comment('decision',(select id from decision),'No')$$,'42501',null,'Nonmember create denied');
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Activity token gives no comment rights');
select is(public.resolve_shared_resource((select d from tokens)),'{"state":"unavailable"}'::jsonb,'Decision token gives no comment rights');
select public.request_project_access((select t from join_token));
select throws_ok($$select public.get_resource_comments('decision',(select id from decision))$$,'42501',null,'Pending requester read denied');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'No')$$,'42501',null,'Pending requester create denied');
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Pending requester token remains unavailable');
select pg_temp.login(6);
select throws_ok($$select public.delete_resource_comment('activity',(select id from activity),(select (doc->>'id')::uuid from first_comment))$$,'42501',null,'Cross-project Organizer cannot moderate');
select is((select count(*)::int from public.resource_comments where project_id=(select id from ctx)),0,'Cross-project Organizer reads zero');
select pg_temp.login(1);
select lives_ok($$select public.delete_resource_comment('activity',(select id from activity),(select (doc->>'id')::uuid from member_comment))$$,'Organizer moderation allowed');
set local role postgres;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.resource_comments'::regclass),'Comments ENABLE and FORCE RLS');
select ok(not has_table_privilege('anon','public.resource_comments','SELECT') and not has_table_privilege('authenticated','public.resource_comments','INSERT') and not has_table_privilege('service_role','public.resource_comments','SELECT'),'Narrow grants');
select is((select count(*)::int from app.domain_events where resource_id=(select (doc->>'id')::uuid from first_comment) and event_type='comment.created'),1,'Exactly one fact on retry');
select is((select actor_user_id from app.domain_events where resource_id=(select (doc->>'id')::uuid from first_comment)),'36000000-0000-4000-8000-000000000001'::uuid,'Event actor authoritative');
select is((select payload from app.domain_events where resource_id=(select (doc->>'id')::uuid from first_comment)),jsonb_build_object('parent_resource_type','activity','parent_resource_id',(select id from activity)),'Minimal event payload has parent binding only');
select ok(not exists(select 1 from public.audit_log where entity_type='resource_comments' and (before ? 'body' or after ? 'body')),'Audit retains metadata without body');
select ok(not exists(select 1 from app.automation_rules where event_type='comment.created'),'No comment notification rule');
select is((select count(*) from public.notifications where project_id=(select id from ctx) and kind not in ('project_join_requested')),(select n from notifications_before),'Comments generated zero notifications');
select ok(not exists(select 1 from app.domain_events e where e.event_type='comment.created' and e.project_id=(select id from ctx) and not exists(select 1 from app.domain_event_processing p where p.event_id=e.id)),'All comment facts processed');
select is((select count(*)::int from app.automation_action_runs a join app.domain_events e on e.id=a.event_id where e.event_type='comment.created' and e.project_id=(select id from ctx)),0,'No default comment action receipts');
select pg_temp.login(2);
create temp table retained as select public.create_resource_comment('decision',(select id from decision),'Retained author history') doc;
set local role postgres;
update public.project_members set status='removed' where project_id=(select id from ctx) and user_id='36000000-0000-4000-8000-000000000002';
select pg_temp.login(2);
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'No')$$,'42501',null,'Removed member cannot create');
select throws_ok($$select public.get_resource_comments('decision',(select id from decision))$$,'42501',null,'Removed member cannot read');
select throws_ok($$select public.delete_resource_comment('decision',(select id from decision),(select (doc->>'id')::uuid from retained))$$,'42501',null,'Removed author cannot delete');
select pg_temp.login(1);
select is(public.get_resource_comments('decision',(select id from decision))->'items'->0->>'author_name','Comment user 2','Historical author retained after removal');
select public.resolve_decision((select id from decision),(select id from public.decision_options where decision_id=(select id from decision) limit 1));
select lives_ok($$select public.create_resource_comment('decision',(select id from decision),'Post-resolution context')$$,'Resolved Decision remains commentable');
select is((select status from public.decisions where id=(select id from decision)),'resolved','Comment does not reopen Decision');
update public.commitments set status='completed' where id=(select id from activity);
select lives_ok($$select public.create_resource_comment('activity',(select id from activity),'Post-completion context')$$,'Completed Activity remains commentable');
select is((select status::text from public.commitments where id=(select id from activity)),'completed','Comment does not reopen Activity');
-- Dedicated thread for stable keyset pages, including ties on timestamp.
create temp table paged as select public.create_decision((select id from ctx),'Pagination',null,null,'[{"title":"A"},{"title":"B"}]') id;
select public.create_resource_comment('decision',(select id from paged),'Page '||i) from generate_series(1,45) i;
set local role postgres;
update public.resource_comments set created_at='2000-01-01 12:00:00+00' where resource_id=(select id from paged);
select pg_temp.login(1);
create temp table page1 as select public.get_resource_comments('decision',(select id from paged)) doc;
select is(jsonb_array_length((select doc->'items' from page1)),20,'Recent page bounded to 20');
create temp table page2 as select public.get_resource_comments('decision',(select id from paged),(select (doc->'next_cursor'->>'created_at')::timestamptz from page1),(select (doc->'next_cursor'->>'id')::uuid from page1)) doc;
create temp table page3 as select public.get_resource_comments('decision',(select id from paged),(select (doc->'next_cursor'->>'created_at')::timestamptz from page2),(select (doc->'next_cursor'->>'id')::uuid from page2)) doc;
select is(jsonb_array_length((select doc->'items' from page2)),20,'Earlier page bounded');
select is(jsonb_array_length((select doc->'items' from page3)),5,'Final five comments');
select is((select doc->'next_cursor' from page3),'null'::jsonb,'Final page no cursor');
select is((select count(distinct x->>'id')::int from (select doc from page1 union all select doc from page2 union all select doc from page3)p cross join lateral jsonb_array_elements(p.doc->'items')x),45,'No missing or duplicate page records');
select ok((select bool_and((x->>'id')::uuid < (y->>'id')::uuid) from page1, lateral jsonb_array_elements(doc->'items') with ordinality a(x,n),lateral jsonb_array_elements(doc->'items') with ordinality b(y,m) where m=n+1),'Equal timestamps ordered by UUID');
select public.create_resource_comment('decision',(select id from paged),'New after page');
select is(public.get_resource_comments('decision',(select id from paged),(select (doc->'next_cursor'->>'created_at')::timestamptz from page1),(select (doc->'next_cursor'->>'id')::uuid from page1)),(select doc from page2),'New insert cannot shift older cursor');
select throws_ok($$select public.get_resource_comments('decision',(select id from paged),now(),null)$$,'22023',null,'Incomplete cursor denied');
set local role postgres;
update public.projects set status='archived' where id=(select id from ctx);
select pg_temp.login(1);
select is(public.get_resource_comments('activity',(select id from activity))->>'can_comment','false','Archive retains read-only comments');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'No')$$,'42501',null,'Archive denies creation');
select throws_ok($$select public.delete_resource_comment('activity',(select id from activity),(select (doc->>'id')::uuid from first_comment))$$,'42501',null,'Archive denies deletion');
set local role postgres;
update public.projects set status='active' where id=(select id from ctx);
select pg_temp.login(1);
select public.soft_delete_commitment((select id from activity));
select is((select count(*)::int from public.resource_comments where resource_id=(select id from activity)),0,'Deleted Activity hides comments');
select throws_ok($$select public.get_resource_comments('activity',(select id from activity))$$,'42501',null,'Deleted Activity read denied');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'No')$$,'42501',null,'Deleted Activity write denied');
select public.soft_delete_decision((select id from decision));
select is((select count(*)::int from public.resource_comments where resource_id=(select id from decision)),0,'Deleted Decision hides comments');
select throws_ok($$select public.create_resource_comment('decision',(select id from decision),'No')$$,'42501',null,'Deleted Decision write denied');
select public.soft_delete_project((select id from ctx));
select is((select count(*)::int from public.resource_comments where project_id=(select id from ctx)),0,'Project cleanup hides all comments');
select throws_ok($$select public.get_resource_comments('decision',(select id from paged))$$,'42501',null,'Deleted project read RPC denied');
select throws_ok($$select public.create_resource_comment('decision',(select id from paged),'No')$$,'42501',null,'Deleted project writes denied');
set local role postgres;
grant select on ctx,activity to anon;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select * from public.resource_comments$$,'42501',null,'Anonymous table access denied');
select throws_ok($$select public.get_resource_comments('activity',(select id from activity))$$,'42501',null,'Anonymous read API denied');
select throws_ok($$select public.create_resource_comment('activity',(select id from activity),'No')$$,'42501',null,'Anonymous create denied');
set local role postgres;
select ok(exists(select 1 from app.domain_events where event_type='comment.created' and project_id=(select id from ctx)),'Historical facts preserved after cleanup');
select ok(exists(select 1 from public.resource_comments where project_id=(select id from ctx)),'Historical comment rows retained privately');
select * from finish();
rollback;
